#include "car_core.h"
#include <stdio.h>
int main(int argc,char**argv){unsigned char g[CAR_W*CAR_H],b[CAR_W*CAR_H];char h[100];vision_state_t s;vision_config_t c;vision_result_t r;vision_reset(&s);vision_config_default(&c);for(int n=1;n<argc;n++){FILE*f=fopen(argv[n],"rb");if(!f)return 2;for(int j=0;j<3;j++)fgets(h,sizeof h,f);if(fread(g,1,sizeof g,f)!=sizeof g)return 3;fclose(f);vision_process(&s,&c,g,b,&r);printf("FILE %s valid=%d pair=%u/%u valid_rows=%u reject=%u error=%.2f threshold=%u contrast=%u\n",argv[n],r.valid,r.paired_rows,r.scanned_rows,r.valid_rows,r.rejected_rows,r.error,r.threshold,r.contrast);for(int y=112;y>=40;y-=6)printf("y=%d left=%d right=%d center=%d flags=%u history_width=%u\n",y,r.left[y],r.right[y],r.center[y],r.edge_flags[y],s.width[y]);}return 0;}
